const RR_CFG={url:'https://tikjmiyrhkcjrxjylmqb.supabase.co',key:'sb_publishable_clr5P9USk7b63MajJmmr9A_Iz0wi_0F',version:'2026.08.16-recurrence1'};
const RR_SESSION='fleet_mvp_session_v2',RR_CASE='fleet_mvp_current_repair';
function rrSession(){try{return JSON.parse(localStorage.getItem(RR_SESSION)||'null')}catch{return null}}
function rrSaveSession(s){if(s)localStorage.setItem(RR_SESSION,JSON.stringify(s))}
async function rrRefresh(){const s=rrSession();if(!s?.refresh_token)throw new Error('Сессия истекла. Войдите снова.');const r=await fetch(`${RR_CFG.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:RR_CFG.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.access_token)throw new Error(d.message||d.msg||'Сессия истекла. Войдите снова.');d.obtained_at=Date.now();rrSaveSession(d);return d}
async function rrRpc(name,params={},retry=true){let s=rrSession();if(!s?.access_token)throw new Error('Нужно войти в систему.');let r=await fetch(`${RR_CFG.url}/rest/v1/rpc/${encodeURIComponent(name)}`,{method:'POST',headers:{apikey:RR_CFG.key,Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(params)});if(r.status===401&&retry){await rrRefresh();return rrRpc(name,params,false)}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.message||x.error||x.hint||`HTTP ${r.status}`)}const t=await r.text();return t?JSON.parse(t):null}
function rrEsc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function rrDate(v){if(!v)return'Дата не указана';const d=new Date(v);return Number.isNaN(d.getTime())?'Дата не указана':new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d)}
function rrPriorRow(x){const facts=[];if(x.diagnosis)facts.push(`Диагноз: ${rrEsc(x.diagnosis)}`);if(x.root_cause)facts.push(`Причина: ${rrEsc(x.root_cause)}`);if(x.preventive_action)facts.push(`Профилактика: ${rrEsc(x.preventive_action)}`);return `<div class="card" style="padding:10px 12px"><div style="font-weight:700">${rrEsc(rrDate(x.closed_at))}</div><div class="muted small" style="margin-top:4px;line-height:1.45">${facts.join(' · ')||'Подробности причины и профилактики не были зафиксированы.'}</div></div>`}
function rrSection(d){const a=d.attention,prev=d.previous_same_category||[];const s=document.createElement('section');s.className='section';s.dataset.rrSection=RR_CFG.version;s.innerHTML=`<div class="alert warning"><div>△</div><div style="flex:1"><div class="alert-title">${rrEsc(a?.label||'Повторная неисправность')}</div><div class="alert-sub">${rrEsc(a?.detail||'На этой машине уже был ремонт той же категории.')}</div>${d.needs_preventive_review?'<div class="alert-sub" style="margin-top:6px"><strong>Что проверить сейчас:</strong> в текущем ремонте ещё не заполнена причина или профилактика. Используйте существующее действие «Причина и профилактика».</div>':''}</div></div>${prev.length?`<details style="margin-top:10px"><summary style="cursor:pointer;font-weight:700">Предыдущие ремонты той же категории · ${prev.length}</summary><div style="display:grid;gap:8px;margin-top:8px">${prev.map(rrPriorRow).join('')}</div></details>`:''}`;return s}
async function rrDecorate(){const main=document.querySelector('.main');if(!main||main.querySelector('[data-rr-section]'))return;const title=document.querySelector('.page-title')?.textContent?.trim();if(title!=='Ремонт')return;const caseId=sessionStorage.getItem(RR_CASE);if(!caseId)return;let d;try{d=await rrRpc('get_repair_recurrence_context',{p_case_id:caseId})}catch{return}if(!d?.repeat_signal||!main.isConnected||main.querySelector('[data-rr-section]'))return;const section=rrSection(d);const work=main.querySelector('[data-rw-section]');if(work)work.before(section);else{const actions=main.querySelector('.action-row');if(actions)actions.before(section);else main.appendChild(section)}}
let rrQueued=false;function rrSchedule(){if(rrQueued)return;rrQueued=true;queueMicrotask(()=>{rrQueued=false;rrDecorate()})}new MutationObserver(rrSchedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('fleet:role-ux-ready',rrSchedule);rrSchedule();
